r"""
Crescopus - CrescoLedger stage 2: screens for time entries, Goodwill /
Recoverable, hourly rates, contributions and recovery settlements

HOW TO USE
  1. Run sql/migration_ledger_time_goodwill.sql in Supabase first (stage 1).
  2. Save this file in your Crescopus project folder (next to wsgi.py).
  3. In PowerShell, in that folder, with your venv active:
         python apply_ledger_screens.py
  4. It lists every file as new / updated / same. Any file it replaces is
     copied first to _backup_apply_ledger_screens\ so you can undo by copying back.

Your .env is never read or changed.
"""
import base64, os, shutil, sys

FILES = [
    ("app/ledger/routes.py", ""),
    ("app/utils.py", ""),
    ("app/templates/ledger/view.html", ""),
    ("app/templates/ledger/entry_form.html", ""),
    ("app/templates/ledger/recovery_form.html", ""),
    ("app/templates/dashboard/index.html", ""),
    ("app/static/css/cresco-ui.css", "")
]
BACKUP = "_backup_apply_ledger_screens"
NEXT = "make sure sql/migration_ledger_time_goodwill.sql has been run in Supabase, restart python wsgi.py and try the ledger, then commit and push."

def main():
    root = os.path.dirname(os.path.abspath(__file__))
    if not os.path.isfile(os.path.join(root, "app", "__init__.py")) or not os.path.isfile(os.path.join(root, "wsgi.py")):
        sys.exit("Stopped: put this file in the Crescopus project folder (next to wsgi.py and the app folder), then run it again.")
    backup = os.path.join(root, BACKUP)
    changed = 0
    for rel, b64 in FILES:
        path = os.path.join(root, *rel.split("/"))
        data = base64.b64decode(b64)
        status = "new     "
        if os.path.exists(path):
            with open(path, "rb") as fh:
                if fh.read() == data:
                    print("same     " + rel)
                    continue
            dest = os.path.join(backup, *rel.split("/"))
            os.makedirs(os.path.dirname(dest), exist_ok=True)
            shutil.copy2(path, dest)
            status = "updated "
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "wb") as fh:
            fh.write(data)
        changed += 1
        print(status + " " + rel)
    print("\nDone - %d of %d files written." % (changed, len(FILES)))
    if os.path.isdir(backup):
        print("Originals of replaced files are in " + BACKUP + os.sep)
    if NEXT:
        print("Next: " + NEXT)

if __name__ == "__main__":
    main()
